API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(OAuth2_OIDC_Validator, "OAuth2/OIDC Validator", "OAuth2, OIDC, JWT", "Validates incoming short-lived JWTs for authentication and authorization.")
    Component(Redis_Cache, "Redis Cache", "Redis", "Provides caching for session and request data to enhance performance.")
    Component(WAF, "WAF", "Web Application Firewall", "Ensures perimeter security and protects against malicious traffic.")
}

Rel(OAuth2_OIDC_Validator, Redis_Cache, "Checks session and token state")

@enduml

Analytics/Reporting Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Analytics/Reporting Container container

Container_Boundary(analytics_reporting_container, "Analytics/Reporting Container") {
    Component(Event_Ingestion_Engine, "Event Ingestion Engine", "Kubernetes, OpenTelemetry", "Ingests and processes asynchronous analytics events streamed from the message broker under EU data residency constraints.")
    Component(Aggregation_and_Reporting_Service, "Aggregation and Reporting Service", "OpenTelemetry, ClickHouse / PostgreSQL", "Processes batch workloads, isolates heavy reporting tasks, and protects real-time search performance.")
    Component(Dashboard_and_Export_Controller, "Dashboard and Export Controller", "HTTPS, JWT-based RBAC, mTLS", "Delivers customized dashboards, scheduled reports, and exports aggregated data via webhooks.")
}

Rel(Event_Ingestion_Engine, Aggregation_and_Reporting_Service, "Persists and processes events", "ClickHouse / PostgreSQL read-replica")
Rel(Aggregation_and_Reporting_Service, Dashboard_and_Export_Controller, "Supplies aggregated data and reports")
@enduml

Message Broker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Message Broker", "Message Broker") {
    Component(Event_Ingestion_Engine, "Event Ingestion Engine", "Kafka / RabbitMQ, Strimzi operator", "Handles incoming asynchronous events from the Circulation Management Container using TLS 1.3 and mTLS & SCRAM-SHA-512.")
    Component(Event_Streaming_Dispatcher, "Event Streaming Dispatcher", "Kafka / RabbitMQ, 3-broker cluster", "Streams events securely to the Analytics/Reporting Container with a replication factor of 2.")
    Component(Dead_Letter_Queue_DLQ_Handler, "Dead Letter Queue (DLQ) Handler", "Kafka / RabbitMQ DLQ", "Routes malformed or unprocessable events securely away from the main event stream.")
}

Rel(Event_Ingestion_Engine, Event_Streaming_Dispatcher, "Forwards validated asynchronous events")
Rel(Event_Ingestion_Engine, Dead_Letter_Queue_DLQ_Handler, "Routes malformed or unprocessable events")
@enduml
